// Generated by Codex, 11 October 2026. Hourly energies are kWh over one hour.
export const defaults = {solar:8.8,battery:13.5,reserve:20,initial:50,batteryPower:3,ev1:10,ev2:8,poolPower:1,poolHours:3,gridLimit:5.75,exportPrice:0.06,terminalPrice:0.15,weather:'sunny'};
export const scenarios = {sunny:{name:'Día soleado',factor:1},cloudy:{name:'Cielo cubierto',factor:0.32},variable:{name:'Nubes y claros',factor:0.68}};
export function validate(c){
 const ranges={solar:[0,30],battery:[0,50],reserve:[0,80],initial:[0,100],batteryPower:[0,10],ev1:[0,20],ev2:[0,20],poolPower:[0,3],poolHours:[0,6],gridLimit:[1,15],exportPrice:[0,0.15],terminalPrice:[0,0.4]};
 for(const [k,[a,b]] of Object.entries(ranges))if(!Number.isFinite(c[k])||c[k]<a||c[k]>b)throw Error(`Valor inválido: ${k}`);
 if(c.initial<c.reserve)throw Error('La carga inicial debe ser igual o superior a la reserva.');
 if(!scenarios[c.weather])throw Error('Escenario desconocido');
 if(!Number.isInteger(c.poolHours))throw Error('La piscina necesita un número entero de horas');
 return c;
}
export function forecast(c){validate(c);return Array.from({length:24},(_,h)=>({h,solar:Math.max(0,Math.sin(Math.PI*(h-7)/11))*(h>=7&&h<=18?c.solar*scenarios[c.weather].factor:0)*(c.weather==='variable'&&h===13?0.4:1),house:0.45+(h>=7&&h<=9?0.65:0)+(h>=18&&h<=22?1.05:0),price:h<8?0.12:h<10?0.20:h<14?0.27:h<18?0.17:h<22?0.34:0.18}));}
function charge(energy,start){const a=Array(24).fill(0);let left=energy;for(let h=start;h<22&&left>1e-9;h++){a[h]=Math.min(3.6,left);left-=a[h];}return {a,left};}
export function simulate(c,starts){validate(c);const f=forecast(c),v1=charge(c.ev1,starts.ev1),v2=charge(c.ev2,starts.ev2);let stored=c.battery*c.initial/100;const initial=stored,floor=c.battery*c.reserve/100,eff=0.95;
 const rows=f.map(x=>{const pool=x.h>=starts.pool&&x.h<starts.pool+c.poolHours?c.poolPower:0,load=x.house+v1.a[x.h]+v2.a[x.h]+pool;let balance=x.solar-load,bc=0,bd=0;
 if(balance>0){bc=Math.min(balance,c.batteryPower,Math.max(0,(c.battery-stored)/eff));stored+=bc*eff;balance-=bc;}else{bd=Math.min(-balance,c.batteryPower,Math.max(0,(stored-floor)*eff));stored-=bd/eff;balance+=bd;}
 const gridIn=Math.max(0,-balance),gridOut=Math.max(0,balance);
 return {...x,pool,ev1:v1.a[x.h],ev2:v2.a[x.h],load,bc,bd,loss:bc*(1-eff)+bd*(1/eff-1),stored,soc:c.battery?stored/c.battery*100:0,gridIn,gridOut,cost:gridIn*x.price-gridOut*c.exportPrice};});
 const sum=k=>rows.reduce((a,r)=>a+r[k],0);const cash=sum('cost'),balanceValue=(stored-initial)*c.terminalPrice;
 return {rows,starts,solar:sum('solar'),load:sum('load'),gridIn:sum('gridIn'),gridOut:sum('gridOut'),cash,balanceValue,cost:cash-balanceValue,finalStored:stored,initialStored:initial,unmet:v1.left+v2.left,peak:Math.max(...rows.map(r=>r.gridIn)),self:sum('solar')?100*(1-sum('gridOut')/sum('solar')):0};
}
export function optimize(config){const c=validate({...defaults,...config});const baseline=simulate(c,{ev1:Math.min(18,22-Math.ceil(c.ev1/3.6)),ev2:Math.min(18,22-Math.ceil(c.ev2/3.6)),pool:Math.min(19,24-c.poolHours)});let best=baseline;
 // Enumerate complete, contiguous charging sessions before the 22:00 deadline.
 const end1=22-Math.ceil(c.ev1/3.6),end2=22-Math.ceil(c.ev2/3.6);let checked=0;
 for(let a=8;a<=end1;a++)for(let b=8;b<=end2;b++)for(let p=9;p<=18-c.poolHours;p++){
  const r=simulate(c,{ev1:a,ev2:b,pool:p});checked++;
  // Grid contract is a preference in this demo; violations are explicitly reported.
  const score=x=>x.cost+Math.max(0,x.peak-c.gridLimit)*2+x.unmet*100;
  if(score(r)<score(best)-1e-8)best=r;
 }
 return {config:c,baseline,optimized:best,saving:baseline.cost-best.cost,checked};
}
export function recommendations(result){const {config:c,baseline:b,optimized:o,saving}=result;const at=h=>`${String(h).padStart(2,'0')}:00`;
 return [
 {title:'Carga los BMW con un horario calculado',text:`BMW 1: ${at(o.starts.ev1)} · ${c.ev1.toFixed(1)} kWh. BMW 2: ${at(o.starts.ev2)} · ${c.ev2.toFixed(1)} kWh. Ambos terminan antes de las 22:00. Se evalúan producción, tarifa y batería.`,type:'Movilidad'},
 {title:'Mueve la depuradora hacia el sol',text:`Piscina desde las ${at(o.starts.pool)} durante ${c.poolHours} h, con ${c.poolPower.toFixed(1)} kW. Se mantiene el mismo tiempo de filtración que en la referencia.`,type:'Piscina'},
 {title:o.peak>c.gridLimit?'Revisa la potencia simultánea':'Mantén la reserva de batería',text:o.peak>c.gridLimit?`El plan alcanza ${o.peak.toFixed(2)} kW de red y supera el límite orientativo de ${c.gridLimit.toFixed(2)} kW. Reduce demanda o separa cargas antes de aplicarlo.`:`Reserva mínima: ${c.reserve} %. Saldo final: ${o.finalStored.toFixed(1)} kWh. El ahorro ajusta el valor de la energía que queda almacenada.`,type:o.peak>c.gridLimit?'Atención':'Batería'},
 {title:'Ahorro trazable, sin promesas anuales',text:`Diferencia estimada: ${saving.toFixed(2)} € en este día sintético. Coste ajustado: ${b.cost.toFixed(2)} € → ${o.cost.toFixed(2)} €. No incluye impuestos, término fijo ni degradación.`,type:'Ahorro'}];
}
export function answer(question,r){const q=question.toLocaleLowerCase('es'),o=r.optimized,c=r.config;
 if(/bmw|coche|cargar|vehículo/.test(q)){const solarHours=o.rows.filter(x=>x.ev1+x.ev2>0),imports=solarHours.reduce((a,x)=>a+x.gridIn,0);return `El plan carga ${c.ev1+c.ev2} kWh: BMW 1 a las ${o.starts.ev1}:00 y BMW 2 a las ${o.starts.ev2}:00. Durante esas horas, la vivienda importa ${imports.toFixed(2)} kWh de red en total. ${imports<0.01?'El escenario no necesita red durante la carga.':'No puedo asegurar una carga exclusivamente solar en este escenario.'} El modelo no atribuye cada kWh de batería a su origen.`;}
 if(/piscina|depura|filtra/.test(q))return recommendations(r)[1].text;
 if(/bater|reserva/.test(q))return recommendations(r)[2].text;
 if(/ahorr|cost|precio|factura/.test(q))return recommendations(r)[3].text;
 if(/por qué|porque|cómo|optim/.test(q))return `Comparo ${r.checked} combinaciones de horarios manteniendo la demanda de ambos BMW y las horas de piscina. Simulo el balance energético cada hora y minimizo coste ajustado, con penalización por superar la potencia orientativa. Es búsqueda discreta con reglas, no un modelo generativo ni un óptimo global de toda la vivienda.`;
 return 'Puedo explicar el escenario calculado: pregunta por BMW, piscina, batería, ahorro o cómo se optimiza. Este asistente local usa reglas y cifras del simulador; no está conectado a un modelo generativo.';
}
